commands:
W=$(realpath ../clone-work/scratch) && cp lib/batcher/batcher.go $W/batcher_judo.go && cp lib/batcher/batcher_test.go $W/batcher_test_judo.go && python3 - "$W" <<'EOF'
import sys
W=sys.argv[1]
p=W+"/batcher_judo.go"; s=open(p).read()
s=s.replace("""	closed   chan struct{}               // close to indicate batcher shut down
	atexit   atexit.FnHandle             // atexit handle
	admitMu  sync.Mutex                  // serializes Commit admission with shutdown
""","""	atexit   atexit.FnHandle             // atexit handle
	mu       sync.Mutex                  // held while admitting requests to in
	closed   bool                        // set under mu when shutdown starts
""")
s=s.replace("""		in:     make(chan request[Item, Result], opt.Size),
		closed: make(chan struct{}),
""","""		in:     make(chan request[Item, Result], opt.Size),
""")
s=s.replace("""		b.admitMu.Lock()
		// show that batcher is shutting down
		close(b.closed)
		// quit the commitLoop by sending a quitRequest message
		//
		// Note that we don't close b.in because that will
		// cause write to closed channel in Commit when we are
		// exiting due to a signal.
		b.in <- request[Item, Result]{quit: true}
		b.admitMu.Unlock()
		b.wg.Wait()""","""		// quit the commitLoop by sending a quitRequest message
		//
		// Note that we don't close b.in because that will
		// cause write to closed channel in Commit when we are
		// exiting due to a signal.
		_ = b.enqueue(request[Item, Result]{quit: true})
		b.wg.Wait()""")
s=s.replace("""	b.admitMu.Lock()
	select {
	case <-b.closed:
		b.admitMu.Unlock()
		return entry, fserrors.FatalError(errors.New("batcher is shutting down"))
	default:
	}
	fs.Debugf(b.f, "Adding %q to batch", name)
	resp := make(chan response[Result], 1)
	b.in <- request[Item, Result]{
		item:   item,
		name:   name,
		result: resp,
	}
	b.admitMu.Unlock()
""","""	resp := make(chan response[Result], 1)
	err = b.enqueue(request[Item, Result]{
		item:   item,
		name:   name,
		result: resp,
	})
	if err != nil {
		return entry, err
	}
""")
s+='''
// enqueue sends req to the commitLoop unless shutdown has started.
//
// Every request sent here is guaranteed to be ahead of the quit
// request, so the commitLoop will always process it.
func (b *Batcher[Item, Result]) enqueue(req request[Item, Result]) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed {
		return fserrors.FatalError(errors.New("batcher is shutting down"))
	}
	if req.quit {
		b.closed = true
	} else {
		fs.Debugf(b.f, "Adding %q to batch", req.name)
	}
	b.in <- req
	return nil
}
'''
open(p,"w").write(s)
t=W+"/batcher_test_judo.go"; s=open(t).read()
s=s.replace("""			select {
			case <-b.closed:
			case <-time.After(100 * time.Millisecond):
			}
""","""			time.Sleep(100 * time.Millisecond)
""")
open(t,"w").write(s)
EOF
echo "{\"Replace\":{\"$PWD/lib/batcher/batcher.go\":\"$W/batcher_judo.go\",\"$PWD/lib/batcher/batcher_test.go\":\"$W/batcher_test_judo.go\"}}" > $W/judo.json
diff -u lib/batcher/batcher.go $W/batcher_judo.go; C=$(realpath ../clone-cache); GOMODCACHE=$C/gomodcache GOCACHE=$C/gocache GOFLAGS=-mod=mod GOPROXY=off GOTOOLCHAIN=local timeout 200 go test -count=1 -race -overlay=$W/judo.json ./lib/batcher 2>&1 | tail -20; git status --short
